public function history(Request $request, Client $client)
{
    $user = $request->user();
    // The parent telemetry permissions are enforced by route middleware.
    // Once they pass, conceal a Client outside the user's Site/object
    // scope so this direct location-history route cannot confirm it exists.
    $this->assertCanDiscoverClientHistory($user, $client);
    $assignment = $this->assertHasActiveTrackingConsent($user, $client);
    $device = $assignment->device;

    // Range pills: today | 24h | 7d | 30d | custom. Default 24h.
    $range = $request->string('range')->toString() ?: '24h';
    [$dateFrom, $dateTo] = $this->resolveHistoryRange(
        $range,
        $request->input('date_from'),
        $request->input('date_to'),
    );
    [$dateFrom, $dateTo] = $this->boundHistoryRangeToAssignment(
        $assignment,
        $dateFrom,
        $dateTo,
    );

    $eventTypesInput = $request->input('event_types');
    $eventTypes = is_array($eventTypesInput)
        ? $eventTypesInput
        : array_filter(array_map('trim', explode(',', (string) $eventTypesInput)));

    $filters = [
        'date_from' => $dateFrom,
        'date_to' => $dateTo,
        'event_types' => $eventTypes,
    ];

    $locations = app(IntegrationEventHistoryService::class)
        ->forDevice($device, $filters, true, $assignment->retention_days);
    $currentAssignment = $this->trackingPrivacy->authorisedClientAssignment($client);
    abort_unless(
        $currentAssignment
            && (int) $currentAssignment->id === (int) $assignment->id
            && (int) $currentAssignment->device_id === (int) $assignment->device_id
            && (int) $currentAssignment->consent_id === (int) $assignment->consent_id,
        403,
    );

    $availableEventTypes = $locations
        ->pluck('event_type')
        ->filter()
        ->unique()
        ->values();

    $client->loadMissing(['site' => fn ($query) => $query->select(['id', 'name'])]);
    $houseGeofence = $client->house_geofence_id
        ? $this->applyGeofenceScope(
            AssetGeofence::query()->whereKey($client->house_geofence_id),
            $request->user(),
        )->first()
        : null;
    $client->setRelation('houseGeofence', $houseGeofence);

    $resident = $device ? $this->buildResidentPayload($device, $client, []) : null;

    return Inertia::render('fleet-assets/resident-tracking/history', [
        'client' => [
            'id' => $client->id,
            'name' => trim(($client->first_name ?? '').' '.($client->last_name ?? '')),
            'house' => $client->site?->name ?? 'Unknown',
            'photo' => $client->profile_photo_url,
        ],
        'resident' => $resident,
        'tracker' => $device ? [
            'id' => $device->id,
            'device_uid' => $device->device_uid,
            'name' => $device->name,
            'serial' => $device->serial_number,
            'status' => $device->status?->value,
            'detail_url' => "/security-devices/devices/{$device->id}",
        ] : null,
        'locations' => $locations,
        'available_event_types' => $availableEventTypes,
        'filters' => [
            'range' => $range,
            'date_from' => $dateFrom ? substr((string) $dateFrom, 0, 10) : null,
            'date_to' => $dateTo ? substr((string) $dateTo, 0, 10) : null,
            'event_types' => $eventTypes,
        ],
        'privacy_status_url' => route(
            'fleet-assets.resident-tracking.privacy-status',
            ['client' => $client->id],
            false,
        ),
        'export_url' => route(
            'fleet-assets.resident-tracking.export',
            ['client' => $client->id],
            false,
        ),
        'can_export' => $user->canDo('assets.telemetry.export'),
        'retention_days' => (int) $assignment->retention_days,
    ])->toResponse($request)->withHeaders($this->privateLocationHeaders());
}

public function index(Request $request)
{
    $user = $request->user();
    abort_unless($this->userCanManage($user), 403);

    $siteIds = $this->access->accessibleSiteIds($user);

    // Provider connection (never expose encrypted values or raw config)
    $providerConnection = IntegrationProviderConnection::query()
        ->forProvider(self::PROVIDER)
        ->first();

    $connectionConfig = is_array($providerConnection?->config) ? $providerConnection->config : [];
    $discoveredSites = collect($connectionConfig['discovered_sites'] ?? [])
        ->map(fn (array $site) => [
            'mapping_token' => $this->mappingToken((string) ($site['external_id'] ?? '')),
            'name' => $site['name'] ?? 'Unknown',
            'device_count' => is_numeric(data_get($site, 'meta.device_count')) ? (int) data_get($site, 'meta.device_count') : null,
        ])
        ->filter(fn (array $site) => $site['mapping_token'] !== '')
        ->values()
        ->all();

    // Site configs with related site metadata
    $siteConfigs = IntegrationSiteConfig::query()
        ->forProvider(self::PROVIDER)
        ->whereIn('site_id', $siteIds)
        ->whereHas('site')
        ->with('site:id,name,type')
        ->orderBy('site_id')
        ->get()
        ->map(fn (IntegrationSiteConfig $config) => [
            'id' => $config->id,
            'site_id' => $config->site_id,
            'site_name' => $config->site?->name ?? 'Unknown site',
            'site_type' => $config->site?->type,
            'status' => $config->status,
            'mapped_external_site_name' => $config->mapped_external_site_name,
            'is_active' => (bool) $config->is_active,
        ])
        ->values()
        ->all();

    // All approved application Sites available for mapping
    $sites = Site::query()
        ->whereIn('id', $siteIds)
        ->orderBy('name')
        ->get(['id', 'name', 'type']);

    // Rooms used for room assignment in settings
    $rooms = SiteRoom::query()
        ->whereIn('site_id', $siteIds)
        ->orderBy('site_id')
        ->orderBy('sort_order')
        ->orderBy('name')
        ->get(['id', 'site_id', 'name']);

    // Synced UniFi devices — reads from canonical Security & Devices registry.
    // Resolves site/room context via device_assignments.
    $syncedDevices = $this->access->visibleDevices($user)
        ->byProvider(self::PROVIDER)
        ->with(['assignments' => fn ($q) => $q->active()])
        ->orderBy('name')
        ->get()
        ->map(function (Device $device) use ($sites, $rooms) {
            // Resolve site/room from active assignment.
            $assignment = $device->assignments->first(fn ($a) => $a->released_at === null);
            $siteId = null;
            $roomId = null;

            if ($assignment) {
                if ($assignment->assignable_type === 'site') {
                    $siteId = $assignment->assignable_id;
                } elseif ($assignment->assignable_type === 'room') {
                    $roomId = $assignment->assignable_id;
                    // Resolve site from room.
                    $room = $rooms->firstWhere('id', $roomId);
                    $siteId = $room?->site_id;
                }
            }

            $site = $siteId ? $sites->firstWhere('id', $siteId) : null;
            $room = $roomId ? $rooms->firstWhere('id', $roomId) : null;

            return [
                'id' => $device->id,
                'site_id' => $siteId,
                'site_name' => $site?->name ?? 'Unassigned',
                'site_type' => $site?->type,
                'room_id' => $roomId,
                'room_name' => $room?->name,
                'name' => $device->name,
                'domain' => $device->domain,
                'category' => $device->category,
                'subcategory' => $device->subcategory,
                'status' => $device->status?->value,
                'health_status' => $device->health_status?->value,
                'model' => $device->model,
                'manufacturer' => $device->manufacturer,
                'firmware_version' => $device->firmware_version,
                'last_seen_at' => $device->last_seen_at?->toISOString(),
                'detail_url' => "/security-devices/devices/{$device->id}",
            ];
        })
        ->sortBy('site_name')
        ->values()
        ->all();

    // Recent sync logs
    $syncLogs = IntegrationSyncLog::query()
        ->forProvider(self::PROVIDER)
        ->where(function ($query) use ($siteIds): void {
            $query->whereNull('site_id')->orWhereIn('site_id', $siteIds);
        })
        ->orderByDesc('created_at')
        ->limit(20)
        ->get()
        ->map(fn (IntegrationSyncLog $log) => [
            'id' => $log->id,
            'action' => $log->action,
            'status' => $log->status,
            'items_processed' => $log->items_processed,
            'items_created' => $log->items_created,
            'items_updated' => $log->items_updated,
            'items_errored' => $log->items_errored,
            'failure_category' => $log->status === IntegrationSyncLog::STATUS_FAILED ? 'provider_failure' : null,
            'started_at' => $log->started_at?->toDateTimeString(),
            'completed_at' => $log->completed_at?->toDateTimeString(),
        ])
        ->values()
        ->all();

    return Inertia::render('security-devices/integrations/unifi', [
        'providerConnection' => $providerConnection ? [
            'status' => $providerConnection->status,
            'secret_last4' => $providerConnection->secret_last4,
            'last_tested_at' => $providerConnection->last_tested_at?->toDateTimeString(),
            'last_synced_at' => $providerConnection->last_synced_at?->toDateTimeString(),
            'sites_synced_at' => $connectionConfig['sites_synced_at'] ?? null,
            'disabled_at' => $providerConnection->disabled_at?->toDateTimeString(),
            'disabled_reason' => in_array($providerConnection->disabled_reason, self::DISABLE_REASONS, true)
                ? $providerConnection->disabled_reason
                : null,
            'requires_credential_replacement' => (bool) $providerConnection->requires_credential_replacement,
            'recovery_credentials_replaced_at' => $providerConnection->recovery_credentials_replaced_at?->toDateTimeString(),
            'defaults' => collect($connectionConfig)->only([
                'refresh_interval_minutes', 'alert_motion_events', 'alert_device_offline',
                'quiet_hours_start', 'quiet_hours_end',
            ])->all(),
        ] : null,
        'discoveredSites' => $discoveredSites,
        'siteConfigs' => $siteConfigs,
        'sites' => $sites,
        'rooms' => $rooms,
        'syncedDevices' => $syncedDevices,
        'syncLogs' => $syncLogs,
        'siteCredentials' => $this->siteCredentials->present($user, self::PROVIDER),
        'can' => [
            'manage' => $this->userCanManage($user),
        ],
    ]);
}

public function index(Request $request): Response
{
    $this->authorizeManage($request);

    $siteIds = $this->siteAccess->accessibleSiteIds(
        $request->user(),
        self::SITE_BYPASS_PERMISSIONS,
    );

    $connections = CalendarSyncConnection::query()
        ->get()
        ->keyBy('provider');

    $providers = collect(self::PROVIDERS)->map(function (string $label, string $key) use ($connections) {
        $conn = $connections->get($key);

        return [
            'key' => $key,
            'label' => $label,
            'configured' => $this->isConfigured($key),
            'connected' => (bool) $conn?->isConnected(),
            'accountEmail' => $conn?->account_email,
            'accountName' => $conn?->account_name,
            'lastSyncedAt' => $conn?->last_synced_at?->toIso8601String(),
            'status' => $conn?->status ?? CalendarSyncConnection::STATUS_DISCONNECTED,
        ];
    })->values()->all();

    $mappingGroups = CalendarSyncMapping::query()
        ->active()
        ->whereIn('site_id', $siteIds)
        ->get()
        ->groupBy(fn (CalendarSyncMapping $mapping): int => (int) $mapping->site_id);
    abort_if(
        $mappingGroups->contains(fn ($siteMappings): bool => $siteMappings->count() > 1),
        409,
        'Calendar mapping configuration requires reconciliation before it can be managed.',
    );
    $mappings = $mappingGroups->map(fn ($siteMappings) => $siteMappings->first());

    $sites = Site::query()
        ->active()
        ->notArchived()
        ->whereNull('archived_at')
        ->whereIn('id', $siteIds)
        ->orderBy('name')
        ->get(['id', 'name', 'type'])
        ->map(function (Site $site) use ($mappings) {
            $mapping = $mappings->get($site->id);

            return [
                'id' => $site->id,
                'name' => $site->name,
                'type' => $site->type,
                'mapping' => $mapping ? $this->mappingPayload($mapping) : null,
            ];
        })
        ->values()
        ->all();

    return Inertia::render('settings/calendar-sync', [
        'providers' => $providers,
        'sites' => $sites,
        'sources' => CalendarSources::pushable(),
        'directions' => [
            ['key' => CalendarSyncMapping::DIRECTION_ONE_WAY, 'label' => 'One-way (push out)'],
            ['key' => CalendarSyncMapping::DIRECTION_TWO_WAY, 'label' => 'Two-way (push + pull busy)'],
        ],
        'settings' => $this->loadSettings(),
        'anyConnected' => collect($providers)->contains('connected', true),
    ]);
}

